package com.bank.bench.calc;

import java.math.BigDecimal;
import java.math.RoundingMode;

// The hot path we want to benchmark: daily interest on a savings balance.
public class InterestCalculator {
    private static final BigDecimal DAYS = new BigDecimal("365");

    // dailyInterest = balance * annualRate / 365, rounded to paise.
    public BigDecimal dailyInterest(BigDecimal balance, BigDecimal annualRatePct) {
        return balance.multiply(annualRatePct)
                .divide(new BigDecimal("100"), 10, RoundingMode.HALF_UP)
                .divide(DAYS, 2, RoundingMode.HALF_UP);
    }
}
