package com.bank.bench.pool;

import java.util.logging.Logger;

// Simulates pre-initialising a connection pool (e.g. HikariCP minimum-idle)
// and priming it with one query BEFORE the measurement window.
public class WarmPoolProvider {
    private static final Logger log = Logger.getLogger(WarmPoolProvider.class.getName());
    private boolean warm = false;

    // In real code: create HikariDataSource, run "SELECT 1", prime caches.
    public void initialiseAndPrime() {
        // Simulate the expensive one-time cost of opening connections + TLS.
        try { Thread.sleep(30); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        warm = true;
        log.info("Connection pool initialised and primed (SELECT 1 run)");
    }

    // A warm read is fast; a cold one would be slow and pollute the histogram.
    public BigDecimalBalance readBalance(String accountId) {
        if (!warm) throw new IllegalStateException("pool not warm — benchmark would be polluted");
        return new BigDecimalBalance(accountId.equals("SAV2001")
                ? new java.math.BigDecimal("1000000")
                : new java.math.BigDecimal("250000"));
    }

    public record BigDecimalBalance(java.math.BigDecimal balance) { }
}
