package com.bank.bench.runner;

import com.bank.bench.calc.InterestCalculator;
import com.bank.bench.pool.WarmPoolProvider;
import java.math.BigDecimal;
import java.util.logging.Logger;
import org.HdrHistogram.Histogram;

// Explicit warmup + measurement phases, result sink to beat dead-code elimination.
public class BenchmarkRunner {
    private static final Logger log = Logger.getLogger(BenchmarkRunner.class.getName());

    private final InterestCalculator calc = new InterestCalculator();
    private final WarmPoolProvider pool = new WarmPoolProvider();
    private final BigDecimal rate = new BigDecimal("6.5");  // 6.5% p.a.

    // Sink prevents C2 from deleting the computation as dead code.
    private volatile BigDecimal sink;

    public Histogram run(int warmupIters, int measureIters) {
        pool.initialiseAndPrime();  // isolate: pool cost OUTSIDE the window

        log.info(() -> "WARMUP: " + warmupIters + " untimed iterations (drive C1->C2)...");
        for (int i = 0; i < warmupIters; i++) {
            BigDecimal bal = pool.readBalance("SAV2001").balance();
            sink = calc.dailyInterest(bal, rate);   // consume result
        }

        log.info(() -> "MEASURE: " + measureIters + " timed iterations into HdrHistogram...");
        Histogram h = new Histogram(60_000_000_000L, 3); // up to 60s in ns, 3 sig digits
        for (int i = 0; i < measureIters; i++) {
            BigDecimal bal = pool.readBalance("SAV2001").balance();
            long start = System.nanoTime();
            sink = calc.dailyInterest(bal, rate);        // the thing we measure
            long latencyNs = System.nanoTime() - start;
            h.recordValue(latencyNs);
        }
        return h;
    }

    public BigDecimal lastResult() { return sink; }
}
