package com.bank.bench;

import com.bank.bench.runner.BenchmarkRunner;
import java.util.logging.Logger;
import org.HdrHistogram.Histogram;

public class BenchmarkDemo {
    private static final Logger log = Logger.getLogger(BenchmarkDemo.class.getName());

    public static void main(String[] args) {
        BenchmarkRunner runner = new BenchmarkRunner();
        Histogram h = runner.run(50_000, 200_000);

        log.info(() -> String.format(
            "RESULT dailyInterest=%s | median=%.3fus p99=%.3fus p99.9=%.3fus max=%.3fus",
            runner.lastResult(),
            h.getValueAtPercentile(50) / 1000.0,
            h.getValueAtPercentile(99) / 1000.0,
            h.getValueAtPercentile(99.9) / 1000.0,
            h.getMaxValue() / 1000.0));

        log.warning("Report percentiles from the MEASURE phase only — never the cold warmup.");
    }
}
