package com.bank.bench;

import com.bank.bench.runner.BenchmarkRunner;
import org.HdrHistogram.Histogram;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class BenchmarkRunnerTest {

    @Test
    void producesNonEmptyHistogramAndConsumesResult() {
        BenchmarkRunner runner = new BenchmarkRunner();
        Histogram h = runner.run(5_000, 20_000);
        assertEquals(20_000, h.getTotalCount());         // every measured iter recorded
        assertNotNull(runner.lastResult());               // sink consumed (no dead code)
        assertTrue(h.getValueAtPercentile(50) > 0);
    }

    @Test
    void warmPoolReadDoesNotThrow() {
        BenchmarkRunner runner = new BenchmarkRunner();
        assertDoesNotThrow(() -> runner.run(1_000, 1_000));
    }
}
